sys_script.script:
(function () {
    var receiptSysId = current.getValue('material_receipt');
    var qcResult = current.getValue('result');
    if (!receiptSysId || !qcResult) return;

    var receiptGr = new GlideRecord('x_2056099_indust_0_mat_rcpt');
    if (receiptGr.get(receiptSysId)) {
        var qtyReceived = parseInt(receiptGr.getValue('quantity_received')) || 0;

        if (qcResult === 'pass') {
            receiptGr.setValue('status', 'passed');
            receiptGr.setValue('quantity_accepted', String(qtyReceived));
            receiptGr.setValue('quantity_rejected', '0');
        } else if (qcResult === 'fail') {
            receiptGr.setValue('status', 'failed');
            receiptGr.setValue('quantity_accepted', '0');
            receiptGr.setValue('quantity_rejected', String(qtyReceived));
        } else if (qcResult === 'conditional_pass') {
            receiptGr.setValue('status', 'partial');
            // For conditional pass, estimate 80% accepted, 20% rejected
            var accepted = Math.round(qtyReceived * 0.8);
            var rejected = qtyReceived - accepted;
            receiptGr.setValue('quantity_accepted', String(accepted));
            receiptGr.setValue('quantity_rejected', String(rejected));
        }
        receiptGr.update();
    }
})();
